        #region TrnFVUImport_Load

        private void TrnFVUImport_Load(object sender, EventArgs e)
        {
            int h = Screen.PrimaryScreen.WorkingArea.Height;
            int w = Screen.PrimaryScreen.WorkingArea.Width;
            this.ClientSize = new Size(w, h);
            //
            GC.Collect();
            //
            //Added by Indrajit on 23-02-2013
            tmrLoginRefresh.Interval = (int)TDSMAN.Classes.TDSMAN.T_pLockInterval * 60000;
            tmrLoginRefresh.Start();
            //-----------
            lblTitle.Text = "Import from TDS/txt File";
            //-- FINANCIAL YEAR
            //-----------
            strSQL = " SELECT ASST_ID," +
                "             FA_YEAR " +
                "      FROM   MST_ASSESSMENT " +
                "      WHERE  VISIBILITY_FLAG = 0 " +
                "      ORDER BY ASST_ID DESC";
            if (dmlService.J_PopulateComboBox(strSQL, ref cmbFinancialYear, 1, J_ComboBoxSelectedIndex.YES) == false) return;
            //-----------
            //-- QUARTER
            //-----------
            string[] strQtr ={ T_Qtr.Q1, T_Qtr.Q2, T_Qtr.Q3, T_Qtr.Q4 };
            dmlService.J_PopulateComboBox(strQtr, ref cmbQuarter, 1);
            //-- FORM NO
            //string[] strQuarterWiseDeducteeReportForm ={ T_FormNo.F24Q, T_FormNo.F26Q, T_FormNo.F27Q, T_FormNo.F27EQ };
            string[] strQuarterWiseDeducteeReportForm = { T_FormNo.F138_24Q + " (" + T_FormNo.F24Q + ")", T_FormNo.F140_26Q + " (" + T_FormNo.F26Q + ")", T_FormNo.F144_27Q + " (" + T_FormNo.F27Q + ")", T_FormNo.F143_27EQ + " (" + T_FormNo.F27EQ + ")"};
            dmlService.J_PopulateComboBox(strQuarterWiseDeducteeReportForm, ref cmbFormNo, 1);
            //-----------
            //-- COMPANY
            //-----------
            //strSQL = " SELECT COMPANY_ID," +
            //    "             COMPANY_NAME & ' [' & TAN_NO & ']'" +
            //    "      FROM   MST_COMPANY " +
            //    "      WHERE  INACTIVE_FLAG = 0 " +
            //    "      ORDER BY COMPANY_NAME";
            //if (dmlService.J_PopulateComboBox(strSQL, ref cmbCompany) == false) return;
            //-----------
            //-- COMPANY
            //-----------
            string[,] strShowCompanyMatrix = {{"MST_COMPANY.COMPANY_ID = 0", "F", "0", "T"},
                                              {"MST_COMPANY.COMPANY_ID > 0", "F", "1", "T"}};
            //
            strSQL = @"SELECT COMPANY_ID,
                              COMPANY_DESC
                       FROM
                       (    SELECT 0                              AS COMPANY_ID,
                             '" + strCreateNewCompanyText + @"' AS COMPANY_DESC
                            FROM   MST_SETUP
                            UNION
                            SELECT COMPANY_ID,
                                   COMPANY_NAME + ' [' + TAN_NO + ']' AS COMPANY_DESC 
                            FROM   MST_COMPANY 
                            WHERE  INACTIVE_FLAG = 0 
                        )MST_COMPANY
                        ORDER BY " + cmnService.J_SQLDBFormat(strShowCompanyMatrix, J_SQLColFormat.Case_End) + " ASC,COMPANY_DESC";
            //--------------------------------------------------------------------------------------
            //-- MODIFIED BY DHRUB TO ADD OPTION [Create New Company] Into Company 
            if (dmlService.J_PopulateComboBox(strSQL, ref cmbCompany) == false) return;
            //--------------------------------------------------------------------------------------
            //set Transaction import to true
            chkTransactionImport.Checked = true;
                
        }

        #endregion

        #region btnSelectTDSPath_Click
        private void btnSelectTDSPath_Click(object sender, EventArgs e)
        {
            //strFVUPath = cmnService.J_OpenFileDialog("TDS File | *.tds", "TDS File | *.tds", "Choose the TDS File to import");
            strFVUPath = cmnService.J_OpenFileDialog("TDS File | *.tds; *.txt", "TDS/Text File | *.tds; *.txt", "Choose the TDS/Text File to import");
            if (strFVUPath != "")
                txtFVUPath.Text = strFVUPath; 
            
        }
        #endregion

