        #region User Defined Functions

        #region ValidateFields
        private bool ValidateFields()
        {
            try
            {
                if (lblSearchMode.Text == J_Mode.Sorting)
                {
                    
                    return true;
                }
                else if (lblSearchMode.Text == J_Mode.Searching)
                {                    
                    return true;
                }
                else
                {
                    //-- Added By Abhishek Dey On 31/10/2019 --
                    #region IS COMPANY ACCESSABLE FOR CLIENT
                    if (TDSMAN.Classes.TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.CLIENT_MACHINE)
                    {
                        if (dmlService.J_IsDatabaseObjectExist("TRN_TAN_USER") == true)
                        {
                            if (TdsMan.IsCompanyAccessible(Convert.ToInt64(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)), TDSMAN.Classes.TDSMAN.T_MACHINE_ID) == false)
                            {
                                cmnService.J_UserMessage("You are not authorised to proceed.");
                                BtnExit.Select();
                                return false;
                            }

                            //if (Convert.ToInt32(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM TRN_TAN_USER WHERE SETUP_ID = " + TDSMAN.Classes.TDSMAN.T_MACHINE_ID + " AND COMPANY_ID = " + )) > 0)

                        }
                    }
                    #endregion
                    //-----------------------------------------


                    //-----------------------------------------------------------------------
                    //-- FINANCILAL YEAR
                    //-----------------------------------------------------------------------
                    if (cmbFinancialYear.SelectedIndex <= 0)
                    {
                        cmnService.J_UserMessage("Financial Year - Cannot be Blank");
                        cmbFinancialYear.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- QTR
                    //-----------------------------------------------------------------------
                    if (cmbQuarter.SelectedIndex <= 0)
                    {
                        cmnService.J_UserMessage("Quarter - Cannot be Blank");
                        cmbQuarter.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- FORM NO
                    //-----------------------------------------------------------------------
                    if (cmbFormNo.SelectedIndex <= 0)
                    {
                        cmnService.J_UserMessage("Form No. - Cannot be Blank");
                        cmbFormNo.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- COMPANY NAME
                    //-----------------------------------------------------------------------
                    if (cmbCompany.SelectedIndex <= 0)
                    {
                        cmnService.J_UserMessage("Company - Cannot be Blank");
                        cmbCompany.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- FVU FILE SELECTED
                    //-----------------------------------------------------------------------
                    if (txtFVUPath.Text.Trim()== "")
                    {
                        cmnService.J_UserMessage("TDS not selected");
                        btnSelectTDSPath.Select();
                        return false;
                    }
                    // FILE SHOULD BE FVU
                    if (Path.GetExtension(txtFVUPath.Text).ToUpper() != ".TDS" )
                    {
                        if (Path.GetExtension(txtFVUPath.Text).ToUpper() != ".TXT")
                        {
                            cmnService.J_UserMessage("Selected file should be a TDS or TXT file");
                            btnSelectTDSPath.Select();
                            return false;
                        }
                    }
                    // FILE EXIST
                    if (cmnService.J_IsFileExist(txtFVUPath.Text) == false)
                    {
                        cmnService.J_UserMessage("Selected " + Path.GetExtension(txtFVUPath.Text) + " file not found");
                        btnSelectTDSPath.Select();
                        return false;
                    }
                    // FILE OPEN
                    if (cmnService.J_IsProcessOpen(txtFVUPath.Text) == true)
                    {
                        cmnService.J_UserMessage("Selected " + Path.GetExtension(txtFVUPath.Text) + " file is open");
                        btnSelectTDSPath.Select();
                        return false;
                    }
                    ////--
                    //strSQL = "SELECT COUNT(COMPANY_ID) + 1 AS MAX_COMPANY_COUNT FROM MST_COMPANY";
                    //if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(strSQL)) > TDSMAN.Classes.TDSMAN.T_pMaxCompanyCount)
                    //{
                    //    if (TDSMAN.Classes.TDSMAN.T_pVersionType == T_VERSION_TYPE.TRIAL_VERSION)
                    //    {
                    //        TrnTrialMessageBox TrialMessageBox = new TrnTrialMessageBox();
                    //        TrialMessageBox.StartPosition = FormStartPosition.CenterScreen;
                    //        TrialMessageBox.lblMessage2.Text = "Trial version supports only One Company.";
                    //        TrialMessageBox.Show();
                    //        return false;
                    //    }
                    //}
                    //if (cmbCompany.SelectedIndex <= 0) return;
                    //if (cmbFormNo.SelectedIndex <= 0) return;
                    //if (cmbQuarter.SelectedIndex <= 0) return;
                    //if (cmbFinancialYear.SelectedIndex <= 0) return;
                    //-- GET BASIC_INFO_ID
                    string strFormNo = cmbFormNo.Text;
                    int intStart = strFormNo.IndexOf('(');
                    int intEnd = strFormNo.IndexOf(')');
                    if (intStart >= 0 && intEnd > intStart)
                    {
                        strFormNo = strFormNo.Substring(intStart + 1, intEnd - intStart - 1);
                    }
                    //
                    long lngBasicInfoIDConso = TdsMan.T_ReturnBasicInfoId(dmlService.J_pCommand, Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)),
                                                                        cmbQuarter.Text,
                                                                        Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)),
                                                                        strFormNo);
                    if (lngBasicInfoIDConso > 0)
                    {
                        if (Path.GetExtension(txtFVUPath.Text).ToUpper() != ".TDS")
                        {
                            //-- CHECK WHETHER DATA IS IMPORTED OR NOT
                            strSQL = @"SELECT IMPORTED_FROM_CONSO_DATE FROM TRN_BASIC_INFO WHERE BASIC_INFO_ID = " + lngBasicInfoIDConso + " AND IMPORTED_FROM_CONSO_DATE IS NOT NULL";
                            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) != "")
                            {
                                lblFooterMessage.Text = "This return was imported via CONSO file on " + Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) + " and cannot be modified. However you can re-import via CONSO File.";
                                lblFooterMessage.ForeColor = System.Drawing.Color.Red;
                                //
                                cmnService.J_UserMessage("This return was imported via CONSO file on " + Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) + " and cannot be modified.\nHowever you can re-import via CONSO File.");
                                return false;
                            }
                        }
                        
                    }
                }
                return true;
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
                return false;
            }
        }
        #endregion

