                                    }
                                    strSDS16RecordNumber = ListLines[i].Substring(intCaratPosition + 1);
                                    strSDS16RecordNumber = ListLines[i].Substring(intCaratPosition + 1, strSDS16RecordNumber.IndexOf("^"));

                                    // 5 SALARY DETAIL - SECTION 16 RECORD NUMBER
                                    // 6 SECTION 16 ID
                                    for (int a = 1; a < 3; a++)
                                    {
                                        intCaratPosition = ListLines[i].IndexOf("^", intCaratPosition + 1);
                                    }
                                    strS16SectionID = ListLines[i].Substring(intCaratPosition + 1);
                                    strS16SectionID = ListLines[i].Substring(intCaratPosition + 1, strS16SectionID.IndexOf("^"));

                                    // 7 TOTAL DEDUCTION
                                    for (int a = 1; a < 2; a++)
                                    {
                                        intCaratPosition = ListLines[i].IndexOf("^", intCaratPosition + 1);
                                    }
                                    strS16TotalDeduction = ListLines[i].Substring(intCaratPosition + 1);
                                    strS16TotalDeduction = ListLines[i].Substring(intCaratPosition + 1, strS16TotalDeduction.IndexOf("^"));

                                    // 8 RECORD HASH
                                    string strUS_16Field = "";
                                    //
                                    if (strS16SectionID == "16(ia)")
                                        strUS_16Field = "US_16_IA";
                                    else if (strS16SectionID == "16(ii)")
                                        strUS_16Field = "US_16_EA";
                                    else
                                        strUS_16Field = "US_16_TE";
                                    //
                                    strSQL = "UPDATE TRN_SALARY_DETAILS SET" +
                                        "            " + strUS_16Field + " = " + cmnService.J_ReturnDoubleValue(strS16TotalDeduction) + " " +
                                        "     WHERE  SALARY_DETAILS_ID = (SELECT MAX(SALARY_DETAILS_ID) FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + ")";
                                    //-----------------------------------------------
                                    if (dmlService.J_ExecSql(strSQL) == false)
                                    {
                                        return false;
                                    }
                                    //
                                    continue;
                                }
                            }
                            #endregion

                            #region SALARY DETAIL [SD-C6A]

                            if (FormNo == T_FormNo.F24Q && cmbQuarter.Text == T_Qtr.Q4)
                            {
                                if (cmnService.J_Mid(ListLines[i], intCaratPosition + 1, 3) == "C6A")
                                {
                                    //intCaratPosition = ListLines[i].IndexOf("^");

                                    // 1 LINE NUMBER
                                    // 2 RECORD TYPE
                                    // 3 BATCH NUMBER
                                    // 4 SALARY DETAIL RECORD NUMBER
                                    for (int a = 1; a < 3; a++)
                                    {
                                        intCaratPosition = ListLines[i].IndexOf("^", intCaratPosition + 1);
                                    }
                                    strSDC6ARecordNumber = ListLines[i].Substring(intCaratPosition + 1);
                                    strSDC6ARecordNumber = ListLines[i].Substring(intCaratPosition + 1, strSDC6ARecordNumber.IndexOf("^"));

                                    // 5 SALARY DETAIL - CHAPTER VI A RECORD NUMBER
                                    // 6 CHAPTER VI A ID
                                    for (int a = 1; a < 3; a++)
                                    {
                                        intCaratPosition = ListLines[i].IndexOf("^", intCaratPosition + 1);
                                    }
                                    strC6ASectionID = ListLines[i].Substring(intCaratPosition + 1);
                                    strC6ASectionID = ListLines[i].Substring(intCaratPosition + 1, strC6ASectionID.IndexOf("^"));

                                    // 7 TOTAL AMOUNT UNDER CHAPTER VI A
                                    for (int a = 1; a < 2; a++)
                                    {
                                        intCaratPosition = ListLines[i].IndexOf("^", intCaratPosition + 1);
                                    }
                                    strC6ATotalAmount = ListLines[i].Substring(intCaratPosition + 1);
                                    strC6ATotalAmount = ListLines[i].Substring(intCaratPosition + 1, strC6ATotalAmount.IndexOf("^"));

                                    // 8 GROSS AMOUNT
                                    for (int a = 1; a < 2; a++)
                                    {
                                        intCaratPosition = ListLines[i].IndexOf("^", intCaratPosition + 1);
                                    }
                                    strC6ATotalGross = ListLines[i].Substring(intCaratPosition + 1);
                                    strC6ATotalGross = ListLines[i].Substring(intCaratPosition + 1, strC6ATotalGross.IndexOf("^"));

                                    // 9 QUALIFYING AMOUNT
                                    for (int a = 1; a < 2; a++)
                                    {
                                        intCaratPosition = ListLines[i].IndexOf("^", intCaratPosition + 1);
                                    }
                                    strC6ATotalQualifying = ListLines[i].Substring(intCaratPosition + 1);
                                    strC6ATotalQualifying = ListLines[i].Substring(intCaratPosition + 1, strC6ATotalQualifying.IndexOf("^"));

                                    // 10 RECORD HASH
                                    string strC6ADedField = "", strC6AGrossField = "", strC6AQualField = "";
                                    //
                                    if (Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) >= T_FinancialYearID.F2018_19ID)
                                    {
                                        if (strC6ASectionID == "80C")
                                        {
                                            strC6ADedField = "CVIA_SEC80C_DED_TOTAL";
                                            strC6AGrossField = "CVIA_SEC80C_GROSS_TOTAL";
                                        }
                                        else if (strC6ASectionID == "80CCC")
                                        {
                                            strC6ADedField = "CVIA_SEC80CCC_DED_AMOUNT";
                                            strC6AGrossField = "CVIA_SEC80CCC_GROSS_AMOUNT";
                                        }
                                        else if (strC6ASectionID == "80CCD(1)")
                                        {
                                            strC6ADedField = "CVIA_SEC80CCD_DED_AMOUNT";
                                            strC6AGrossField = "CVIA_SEC80CCD_GROSS_AMOUNT";
                                        }
                                        else if (strC6ASectionID == "80CCD(1B)")
                                        {
                                            strC6ADedField = "CVIA_SEC80CCD_1B_DED_AMOUNT";
                                            strC6AGrossField = "CVIA_SEC80CCD_1B_GROSS_AMOUNT";
                                        }
                                        else if (strC6ASectionID == "80CCD(2)")
                                        {
                                            strC6ADedField = "CVIA_SEC80CCD_2_DED_AMOUNT";
                                            strC6AGrossField = "CVIA_SEC80CCD_2_GROSS_AMOUNT";
                                        }
                                        else if (strC6ASectionID == "80D")
                                        {
                                            strC6ADedField = "CVIA_SEC80D_DED_AMOUNT";
                                            strC6AGrossField = "CVIA_SEC80D_GROSS_AMOUNT";
                                        }
                                        else if (strC6ASectionID == "80E")
                                        {
                                            strC6ADedField = "CVIA_SEC80E_DED_AMOUNT";
                                            strC6AGrossField = "CVIA_SEC80E_GROSS_AMOUNT";
                                        }
                                        else if (strC6ASectionID == "80G")
                                        {
                                            strC6ADedField = "CVIA_SEC80G_DED_AMOUNT";
                                            strC6AGrossField = "CVIA_SEC80G_GROSS_AMOUNT";
                                            strC6AQualField = "CVIA_SEC80G_QUAL_AMOUNT";
                                        }
                                        else if (strC6ASectionID == "80TTA")
                                        {
                                            strC6ADedField = "CVIA_SEC80TTA_DED_AMOUNT";
                                            strC6AGrossField = "CVIA_SEC80TTA_GROSS_AMOUNT";
                                            strC6AQualField = "CVIA_SEC80TTA_QUAL_AMOUNT";
                                        }
                                        else if (strC6ASectionID == "OTHERS")
                                        {
                                            strC6ADedField = "CVIA_OTH_DED_TOTAL";
                                            strC6AGrossField = "CVIA_OTH_GROSS_TOTAL";
                                            strC6AQualField = "CVIA_OTH_QUAL_TOTAL";
                                        }
                                        else if (strC6ASectionID == "80CCH") //-- 2024/04/29
                                        {
                                            strC6ADedField = "CVIA_SEC80CCH_DED_AMOUNT";
                                            strC6AGrossField = "CVIA_SEC80CCH_GROSS_AMOUNT";
                                        }
                                        else if (strC6ASectionID == "80CCH(1)") //-- 2024/04/29
                                        {
                                            strC6ADedField = "CVIA_SEC80CCH_1_DED_AMOUNT";
                                            strC6AGrossField = "CVIA_SEC80CCH_1_GROSS_AMOUNT";

                                        }
                                        //--                  
                                        if (strC6ADedField != "")
                                        {
                                            strSQL = "UPDATE TRN_SALARY_DETAILS SET" +
                                                    "            " + strC6ADedField + " = " + cmnService.J_ReturnDoubleValue(strC6ATotalAmount) + "," +
                                                    "            " + strC6AGrossField + " = " + cmnService.J_ReturnDoubleValue(strC6ATotalGross) + " " +
                                                    "     WHERE  SALARY_DETAILS_ID = (SELECT MAX(SALARY_DETAILS_ID) FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + ")";
                                        }
                                        //-----------------------------------------------
                                        if (dmlService.J_ExecSql(strSQL) == false)
                                        {
                                            return false;
                                        }
                                        //--
                                        strSQL = "UPDATE TRN_SALARY_DETAILS SET" +
                                        "         CVIA_SEC80CCE_TOTAL_GROSS_AMOUNT = CVIA_SEC80C_GROSS_TOTAL + CVIA_SEC80CCC_GROSS_AMOUNT + CVIA_SEC80CCD_GROSS_AMOUNT," +
                                        "         CVIA_SEC80CCE_TOTAL_DED_AMOUNT   = CVIA_SEC80C_DED_TOTAL + CVIA_SEC80CCC_DED_AMOUNT + CVIA_SEC80CCD_DED_AMOUNT " +
                                        "     WHERE  SALARY_DETAILS_ID = (SELECT MAX(SALARY_DETAILS_ID) FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + ")";
                                        //-----------------------------------------------
                                        if (dmlService.J_ExecSql(strSQL) == false)
                                        {
                                            return false;
                                        }
                                        //--
                                        if (strC6ASectionID == "80G" || strC6ASectionID == "80TTA" || strC6ASectionID == "OTHERS")
                                        {
                                            //--                                       
                                            strSQL = "UPDATE TRN_SALARY_DETAILS SET" +
                                                "            " + strC6AQualField + " = " + cmnService.J_ReturnDoubleValue(strC6ATotalQualifying) + " " +
                                                "     WHERE  SALARY_DETAILS_ID = (SELECT MAX(SALARY_DETAILS_ID) FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + ")";
                                            //-----------------------------------------------
                                            if (dmlService.J_ExecSql(strSQL) == false)
                                            {
                                                return false;
                                            }
                                            //--
                                        }
                                    }
                                    else
                                    {
                                        if (strC6ASectionID == "80CCE")
                                            strC6ADedField = "CVIA_SEC80CCE_TOTAL_DED_AMOUNT";
                                        else if (strC6ASectionID == "80CCF")
                                            strC6ADedField = "CVIA_SEC80CCF_DED_AMOUNT";
                                        else
                                            strC6ADedField = "CVIA_OTH_DED_TOTAL";
                                        //--
                                        strSQL = "UPDATE TRN_SALARY_DETAILS SET" +
                                            "            " + strC6ADedField + " = " + cmnService.J_ReturnDoubleValue(strC6ATotalAmount) + " " +
                                            "     WHERE  SALARY_DETAILS_ID = (SELECT MAX(SALARY_DETAILS_ID) FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + ")";
                                        //-----------------------------------------------
                                        if (dmlService.J_ExecSql(strSQL) == false)
                                        {
                                            return false;
                                        }
                                        //--
                                    }
                                    //
                                    continue;
                                }
                            }
                            #endregion
                            //
                            continue;
                        }


                        #endregion

                    }
                    catch (Exception err)
                    {
                        cmnService.J_UserMessage(err.Message + i.ToString());
                        return false;
                    }

                }
                return true;
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message + NumberOfLines.ToString());
                return false;
            }
        }

