                     " AS SECTION_115BAC_FLAG," +

                     "       " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".NON_RESIDENT AS NON_RESIDENT," +
                     "       " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".PERMANENT_ESTABLISHMENT AS PERMANENT_ESTABLISHMENT " +

                     //========================================================
                     // FROM / JOINS
                     //========================================================
                     "FROM ((((((" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD;
                    // Deductee master - PAN + NAME
                if (FormNo == T_FormNo.F24Q)
                    strSQL = strSQL + " LEFT JOIN MST_EMPLOYEE AS MST_PARTY " +
                     " ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".DEDUCTEE_PAN = MST_PARTY.EMPLOYEE_PAN " +
                     " AND " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".DEDUCTEE_NAME = MST_PARTY.EMPLOYEE_NAME) ";
                else
                    strSQL = strSQL + " LEFT JOIN MST_DEDUCTEE AS MST_PARTY " +
                     " ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".DEDUCTEE_PAN = MST_PARTY.DEDUCTEE_PAN " +
                     " AND " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".DEDUCTEE_NAME = MST_PARTY.DEDUCTEE_NAME) ";

                strSQL = strSQL + " LEFT JOIN MST_SECTION " +
                     " ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".SECTION_NO = MST_SECTION.SECTION_NAME) " +

                     " LEFT JOIN MST_REASON " +
                     " ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".NON_DEDUCTION_FLAG = MST_REASON.REASON) " +

                     " LEFT JOIN MST_TDS_APPLICABILITY " +
                     " ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".TDS_APPLICABILITY_CODE = MST_TDS_APPLICABILITY.TDS_APPLICABILITY_CODE) " +

                     " LEFT JOIN " +
                     " (" +
                     "     SELECT REMITTANCE_ID, REMITTANCE_CODE " +
                     "     FROM MST_REMITTANCE " +
                     "     WHERE VALID_UPTO_ASST_ID = 0 " +
                     "     AND INACTIVE_FLAG = 0 " +
                     " ) AS MST_R " +
                     " ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".REMITTANCE_CODE = MST_R.REMITTANCE_CODE) " +

                     " LEFT JOIN MST_COUNTRY " +
                     " ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DD + ".COUNTRY_CODE = MST_COUNTRY.COUNTRY_CODE) " +

                     " WHERE MST_REASON.FORM_NO = '" + strFormNo + "' ";

                strSQL = strSQL +
                         " AND MST_SECTION.FORM_NAME = '" + strFormNo + "'" +
                         " AND MST_SECTION.DIFF_RATES = 0 ";

                if (dmlService.J_ExecSql(strSQL) == false)
