                         "ON    TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID  = TRN_CHALLAN.BASIC_INFO_ID " +
                         "SET   TRN_DEDUCTEE_DETAILS.CHALLAN_ID     = TRN_CHALLAN.CHALLAN_ID " +
                         "WHERE TRN_DEDUCTEE_DETAILS.CHALLAN_ID = TRN_CHALLAN.SL_NO " +
                         "AND   TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID  = " + BasicInfoID + "";

